import{_ as t,o as r,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"開發者手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/index.md","filePath":"zh-TW/dev-guide/index.md","lastUpdated":1788334237000}'),a={name:"zh-TW/dev-guide/index.md"};function c(i,e,l,n,s,h){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="開發者手冊" tabindex="-1">開發者手冊 <a class="header-anchor" href="#開發者手冊" aria-label="Permalink to &quot;開發者手冊&quot;">​</a></h1><p>歡迎查閱 Lertaro 開發者參考手冊。Lertaro 採用先進的解耦架構與開放的外掛模組化生態體系，提供了官方 SDK 組件 <code>Lertaro.PluginSdk</code>。開發者可以透過引用該 SDK，為 Lertaro 貢獻自訂搜尋來源、擴充快顯動作、深度適配第三方檔案管理器與原生對話方塊，或者自訂美化主題與檔案預覽元件。</p><h2 id="_1-架構與開發流程" tabindex="-1">1. 架構與開發流程 <a class="header-anchor" href="#_1-架構與開發流程" aria-label="Permalink to &quot;1. 架構與開發流程&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">系統架構設計</a></strong> —— 詳解 SYSTEM 級 Windows 索引服務、使用者態 WPF 互動處理程序與獨立鍵盤攔截處理程序的三處理程序隔離模型與具名管道 IPC 通訊機制。</li><li><strong><a href="./getting-started.html">快速上手指南</a></strong> —— 從零建立外掛模組類別庫專案、引用 SDK、實作 <code>IPlugin</code> 入口以及本機偵錯的最佳實踐。</li><li><strong><a href="./packaging.html">封裝與分發</a></strong> —— 外掛模組組件目錄結構規範、第三方託管/原生相依庫打包、多語言 JSON 資源內嵌與 PostBuild 自動部署。</li><li><strong><a href="./examples.html">官方外掛模組範例</a></strong> —— 深度剖析隨包開源的 <code>CoreExtensions</code>、<code>PinyinAlias</code> 與 <code>FlowLauncherBridge</code> 等真實外掛模組的最佳實踐程式碼。</li></ul><h2 id="_2-外掛模組-sdk-介面參考" tabindex="-1">2. 外掛模組 SDK 介面參考 <a class="header-anchor" href="#_2-外掛模組-sdk-介面參考" aria-label="Permalink to &quot;2. 外掛模組 SDK 介面參考&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK 模組分類</th><th style="text-align:left;">核心介面與服務</th><th style="text-align:left;">關鍵功能說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">核心檢索與動作</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IFullSearchFileResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">貢獻靜態索引來源、高頻即時計算答案、完整搜尋視窗檔案結果、非 ASCII 別名轉寫引擎、尾部 Token 後綴處理器以及靜態/動態快顯動作功能表。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">系統與對話方塊適配</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">探測前景管理器活動目錄、掛載原生檔案對話方塊、內嵌搜尋列並雙向同步選取狀態、貢獻滑鼠快速導覽階層式功能表。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">介面與預覽擴充</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">擴充側邊欄篩選分類、表格檢視自訂欄、快速面板動態工作區索引標籤、QuickLook 自訂轉譯器與縮圖擷取、WPF 資源字典主題包與多語言 i18n。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">共用抽象契約</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">檢索結果唯讀資料契約、奈秒級檔案時間戳記與大小中繼資料、宿主視窗安全控制控制代碼與基於結構描述驅動的原生設定表單。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">宿主開放服務</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">宿主暴露的高效能基礎設施：fzf 模糊比對與反白遮罩、多語言剖析、帶快取圖示擷取、收藏管理與歷程讀取、背景目錄索引代理、使用者資料目錄隔離及 Shell 原生檔案操作。</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>本手冊所有介面簽章、方法參數與行為契約均直接對照 <code>Lertaro.PluginSdk</code> 原始碼嚴格編寫並校驗。</p></div>',7)])])}const S=t(a,[["render",c]]);export{b as __pageData,S as default};
